package com.example.campsitelottery

import com.google.firebase.firestore.DocumentId
import java.util.Date

/**
 * Documentation generated by Gemini
 * Represents the status lifecycle of a campsite reservation.
 */
enum class ReservationStatus {
    /** Won lottery, awaiting entrant confirmation or booking. */
    PENDING,
    /** Successfully booked and confirmed active reservation. */
    CONFIRMED,
    /** Cancelled by the entrant. */
    CANCELLED_BY_ENTRANT,
    /** Rejected by the campsite owner. */
    REJECTED_BY_OWNER,
    /** Past completed reservation. */
    COMPLETED
}

/**
 * Documentation generated by Gemini
 * Represents a campsite reservation instance in the system.
 *
 * @property reservationId Firestore document ID for this reservation.
 * @property campsiteId ID of the reserved campsite.
 * @property entrantId Device/User ID of the entrant making the reservation.
 * @property ownerId Device/User ID of the campsite owner.
 * @property checkInDate Starting date of the stay.
 * @property checkOutDate Ending date of the stay.
 * @property reservedDates List of specific reserved dates for multi-day selections.
 * @property totalPrice Total booking price.
 * @property status Current [ReservationStatus] of this reservation.
 * @property rulesAccepted Indicates whether the entrant accepted the campsite rules.
 * @property createdAt Timestamp when the reservation record was created.
 * @property updatedAt Timestamp when the reservation record was last updated.
 */
data class Reservation(
    @DocumentId
    val reservationId: String = "",
    var campsiteId: String = "",
    var entrantId: String = "",
    var ownerId: String = "",

    // Booking dates & details
    var checkInDate: Date? = null,
    var checkOutDate: Date? = null,
    var reservedDates: List<Date> = emptyList(), // Supports multi date selections
    var totalPrice: Double = 0.0,

    // Status and Policy Compliance
    var status: ReservationStatus = ReservationStatus.PENDING,
    var rulesAccepted: Boolean = false,

    // Timestamps
    var createdAt: Date = Date(),
    var updatedAt: Date = Date()
) {
    /**
     * Documentation generated by Gemini
     * Required no-argument secondary constructor for Firestore deserialization.
     */
    constructor() : this(
        reservationId = "",
        campsiteId = "",
        entrantId = "",
        ownerId = "",
        checkInDate = null,
        checkOutDate = null,
        reservedDates = emptyList(),
        totalPrice = 0.0,
        status = ReservationStatus.PENDING,
        rulesAccepted = false,
        createdAt = Date(),
        updatedAt = Date()
    )

    /**
     * Documentation generated by Gemini
     * Helper to check if the reservation is currently active/confirmed.
     *
     * @return True if [status] is [ReservationStatus.CONFIRMED], false otherwise.
     */
    fun isActive(): Boolean {
        return status == ReservationStatus.CONFIRMED
    }
}